CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.account_ready(_user_id) AND (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='admin') OR (NOT EXISTS (SELECT 1 FROM public.profiles WHERE username='administrador') AND EXISTS (SELECT 1 FROM public.profiles p JOIN public.user_roles r ON r.user_id=p.id WHERE p.id=_user_id AND p.username='cauet.mello' AND r.role='developer'))) $$;